  ("Tour of Historic Fenway Park", "/tours/Boston/Tour-of-Historic-Fenway-Park-Americas-Most-Beloved-Ballpark/d678-43406P1", "Go behind the scenes at America's oldest ballpark, including a stop atop the Green Monster.", "1 hour", 45, 4.7, "3,400+"),
  ("Boston Celtics Game at TD Garden", "/tours/Boston/Boston-Celtics-Basketball-Game-at-TD-Garden/d678-5576124P94", "Game tickets to see the most decorated franchise in the NBA.", "About 2 hours", 99, 5.0, "New"),
  ("Boston Bruins Game at TD Garden", "/tours/Boston/Boston-Bruins-Ice-Hockey-Game-at-TD-Garden/d678-5576124P109", "Original Six hockey in one of the loudest arenas in the league.", "About 3 hours", 71, 5.0, "New"),
  ("New England Patriots Game at Gillette Stadium", "/tours/Massachusetts/New-England-Patriots-Football-Game-at-Gillette-Stadium/d22172-5576124P158", "Game tickets for a fall Sunday in Foxborough, about 30 miles southwest of the city.", "About 4 hours", 152, None, "New"),
  ("Boston Duck Boat Tour", "/tours/Boston/Boston-Duck-Boat-Sightseeing-City-Tour-with-Cruise/d678-3037DUCK", "Ride the same boats Boston's champions use for their victory parades.", "80 min", 62, 4.6, "10,000+"),
